{
  "name": "GovPrep AI",
  "description": "An AI-powered practice platform for Government Competitive Exams, specializing in timed Arithmetic and Reasoning tests."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Subject {
  ARITHMETIC = 'Arithmetic',
  REASONING = 'Reasoning'
}

export enum Difficulty {
  EASY = 'Easy',
  MEDIUM = 'Medium',
  HARD = 'Hard'
}

export interface Question {
  id: number;
  text: string;
  options: string[];
  correctAnswerIndex: number;
  explanation: string;
}

export interface QuizConfig {
  subject: Subject;
  difficulty: Difficulty;
  questionCount: number;
  timeLimitMinutes: number; // Total time for the quiz
}

export interface QuizState {
  currentQuestionIndex: number;
  answers: Record<number, number>; // questionId -> selectedOptionIndex
  isFinished: boolean;
  score: number;
  timeRemaining: number;
  startTime: number;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Subject, Difficulty, Question } from "../types";

const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error("API Key is missing. The app will likely fail to generate questions.");
}

const ai = new GoogleGenAI({ apiKey: apiKey || 'dummy-key-for-types' });

export const generateQuestions = async (
  subject: Subject,
  difficulty: Difficulty,
  count: number
): Promise<Question[]> => {
  const modelName = "gemini-3-flash-preview";

  const prompt = `
    You are an expert examiner for competitive government exams (like SSC, Banking, Railways, CSAT).
    Generate ${count} unique, high-quality, multiple-choice questions for the subject: "${subject}".
    Difficulty Level: ${difficulty}.

    For Arithmetic: Focus on quantitative aptitude, data interpretation, number systems, algebra, arithmetic word problems.
    For Reasoning: Focus on logical reasoning, series, analogies, syllogisms, blood relations, coding-decoding.

    Ensure the questions are solvable within 1-2 minutes each. 
    Do not use complex LaTeX. Use plain text or standard Unicode symbols for math.
  `;

  const questionSchema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.INTEGER },
        text: { type: Type.STRING, description: "The question text" },
        options: { 
          type: Type.ARRAY, 
          items: { type: Type.STRING },
          description: "An array of 4 possible answers"
        },
        correctAnswerIndex: { 
          type: Type.INTEGER, 
          description: "The index (0-3) of the correct answer in the options array" 
        },
        explanation: { 
          type: Type.STRING, 
          description: "A brief explanation of the solution" 
        }
      },
      required: ["id", "text", "options", "correctAnswerIndex", "explanation"]
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: questionSchema,
        systemInstruction: "You are a helpful and precise exam generator AI."
      }
    });

    const jsonText = response.text;
    if (!jsonText) {
      throw new Error("No text returned from Gemini API");
    }

    const questions = JSON.parse(jsonText) as Question[];

    // Ensure IDs are unique and sequential for our frontend logic
    return questions.map((q, index) => ({
      ...q,
      id: index
    }));

  } catch (error) {
    console.error("Failed to generate questions:", error);
    throw new Error("Could not generate questions. Please try again.");
  }
};

import React, { useState } from 'react';
import { Subject, Difficulty, QuizConfig } from '../types';
import { BookOpen, Brain, Clock, Settings, Play } from 'lucide-react';

interface WelcomeScreenProps {
  onStart: (config: QuizConfig) => void;
  isLoading: boolean;
}

const WelcomeScreen: React.FC<WelcomeScreenProps> = ({ onStart, isLoading }) => {
  const [subject, setSubject] = useState<Subject>(Subject.ARITHMETIC);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.MEDIUM);
  const [questionCount, setQuestionCount] = useState<number>(5);

  // Calculate suggested time based on difficulty and count
  const getSuggestedTime = () => {
    const baseTimePerQ = difficulty === Difficulty.EASY ? 1 : difficulty === Difficulty.MEDIUM ? 1.5 : 2;
    return Math.ceil(questionCount * baseTimePerQ);
  };

  const handleStart = () => {
    onStart({
      subject,
      difficulty,
      questionCount,
      timeLimitMinutes: getSuggestedTime()
    });
  };

  return (
    <div className="max-w-4xl mx-auto p-6 animate-fade-in">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-slate-900 mb-4 tracking-tight">
          Gov<span className="text-blue-600">Prep</span> AI
        </h1>
        <p className="text-slate-600 text-lg max-w-2xl mx-auto">
          Master Arithmetic and Reasoning for your upcoming competitive exams with custom, AI-generated mock tests.
        </p>
      </div>

      <div className="grid md:grid-cols-2 gap-8 mb-10">
        {/* Arithmetic Card */}
        <div 
          onClick={() => setSubject(Subject.ARITHMETIC)}
          className={`cursor-pointer group relative p-6 rounded-2xl border-2 transition-all duration-300 ${
            subject === Subject.ARITHMETIC 
              ? 'border-blue-600 bg-blue-50/50 shadow-xl scale-[1.02]' 
              : 'border-slate-200 bg-white hover:border-blue-300 hover:shadow-md'
          }`}
        >
          <div className="flex items-center gap-4 mb-4">
            <div className={`p-3 rounded-xl ${subject === Subject.ARITHMETIC ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-600'}`}>
              <BookOpen size={24} />
            </div>
            <h3 className="text-xl font-bold text-slate-800">Arithmetic</h3>
          </div>
          <p className="text-slate-600 mb-4">
            Quantitative aptitude, data interpretation, number systems, and algebra.
          </p>
          <div className="absolute top-6 right-6">
            <div className={`w-4 h-4 rounded-full border-2 ${subject === Subject.ARITHMETIC ? 'border-blue-600 bg-blue-600' : 'border-slate-300'}`}></div>
          </div>
        </div>

        {/* Reasoning Card */}
        <div 
          onClick={() => setSubject(Subject.REASONING)}
          className={`cursor-pointer group relative p-6 rounded-2xl border-2 transition-all duration-300 ${
            subject === Subject.REASONING 
              ? 'border-purple-600 bg-purple-50/50 shadow-xl scale-[1.02]' 
              : 'border-slate-200 bg-white hover:border-purple-300 hover:shadow-md'
          }`}
        >
          <div className="flex items-center gap-4 mb-4">
            <div className={`p-3 rounded-xl ${subject === Subject.REASONING ? 'bg-purple-600 text-white' : 'bg-slate-100 text-slate-600'}`}>
              <Brain size={24} />
            </div>
            <h3 className="text-xl font-bold text-slate-800">Reasoning</h3>
          </div>
          <p className="text-slate-600 mb-4">
            Logical reasoning, verbal/non-verbal ability, patterns, and critical thinking.
          </p>
          <div className="absolute top-6 right-6">
            <div className={`w-4 h-4 rounded-full border-2 ${subject === Subject.REASONING ? 'border-purple-600 bg-purple-600' : 'border-slate-300'}`}></div>
          </div>
        </div>
      </div>

      {/* Settings Section */}
      <div className="bg-white rounded-2xl shadow-lg border border-slate-100 p-8">
        <div className="flex items-center gap-2 mb-6 text-slate-800 font-semibold border-b pb-4">
          <Settings size={20} />
          <h2>Configuration</h2>
        </div>

        <div className="grid md:grid-cols-2 gap-8">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Difficulty Level</label>
            <div className="flex gap-2">
              {[Difficulty.EASY, Difficulty.MEDIUM, Difficulty.HARD].map((level) => (
                <button
                  key={level}
                  onClick={() => setDifficulty(level)}
                  className={`flex-1 py-2 px-4 rounded-lg text-sm font-medium transition-colors ${
                    difficulty === level
                      ? 'bg-slate-800 text-white'
                      : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                  }`}
                >
                  {level}
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Number of Questions</label>
            <div className="flex gap-2">
              {[5, 10, 15].map((count) => (
                <button
                  key={count}
                  onClick={() => setQuestionCount(count)}
                  className={`flex-1 py-2 px-4 rounded-lg text-sm font-medium transition-colors ${
                    questionCount === count
                      ? 'bg-slate-800 text-white'
                      : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                  }`}
                >
                  {count} Qs
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="mt-8 flex items-center justify-between bg-slate-50 p-4 rounded-xl border border-slate-100">
          <div className="flex items-center gap-3 text-slate-600">
            <Clock size={20} className="text-rose-500" />
            <span className="font-medium">Estimated Time: <span className="text-slate-900">{getSuggestedTime()} Minutes</span></span>
          </div>
          <button
            onClick={handleStart}
            disabled={isLoading}
            className={`flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-xl transition-all shadow-md hover:shadow-lg transform active:scale-95 ${
              isLoading ? 'opacity-70 cursor-wait' : ''
            }`}
          >
            {isLoading ? (
              <>Generating...</>
            ) : (
              <>
                Start Practice <Play size={18} fill="currentColor" />
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default WelcomeScreen;

import React, { useEffect, useState } from 'react';
import { Question, QuizState } from '../types';
import { Clock, ChevronRight, ChevronLeft, CheckCircle, Circle, AlertCircle } from 'lucide-react';

interface QuizScreenProps {
  questions: Question[];
  timeLimitMinutes: number;
  onFinish: (state: QuizState) => void;
}

const QuizScreen: React.FC<QuizScreenProps> = ({ questions, timeLimitMinutes, onFinish }) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [timeRemaining, setTimeRemaining] = useState(timeLimitMinutes * 60);
  const [startTime] = useState(Date.now());
  const [isSubmitConfirmOpen, setIsSubmitConfirmOpen] = useState(false);

  const currentQuestion = questions[currentQuestionIndex];
  const isAnswered = answers[currentQuestion.id] !== undefined;

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeRemaining((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          handleFinish();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleFinish = () => {
    // Calculate score
    let score = 0;
    questions.forEach(q => {
      if (answers[q.id] === q.correctAnswerIndex) {
        score++;
      }
    });

    onFinish({
      currentQuestionIndex,
      answers,
      isFinished: true,
      score,
      timeRemaining,
      startTime
    });
  };

  const handleOptionSelect = (optionIndex: number) => {
    setAnswers(prev => ({
      ...prev,
      [currentQuestion.id]: optionIndex
    }));
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const answeredCount = Object.keys(answers).length;
  const progressPercent = (answeredCount / questions.length) * 100;

  return (
    <div className="max-w-6xl mx-auto p-4 md:p-6 h-[calc(100vh-2rem)] flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6">
        <div>
          <h2 className="text-lg font-bold text-slate-800">Section: General Awareness</h2>
          <div className="text-sm text-slate-500">Question {currentQuestionIndex + 1} of {questions.length}</div>
        </div>

        <div className={`flex items-center gap-2 text-xl font-mono font-bold px-4 py-2 rounded-lg ${timeRemaining < 60 ? 'bg-red-50 text-red-600 animate-pulse' : 'bg-blue-50 text-blue-700'}`}>
          <Clock size={20} />
          {formatTime(timeRemaining)}
        </div>
      </div>

      <div className="flex-1 flex flex-col md:flex-row gap-6 overflow-hidden">
        {/* Main Question Area */}
        <div className="flex-1 flex flex-col bg-white rounded-2xl shadow-lg border border-slate-200 overflow-hidden">
          {/* Progress Bar */}
          <div className="h-1 bg-slate-100 w-full">
            <div 
              className="h-full bg-blue-500 transition-all duration-300"
              style={{ width: `${((currentQuestionIndex + 1) / questions.length) * 100}%` }}
            />
          </div>

          <div className="p-6 md:p-8 overflow-y-auto flex-1">
            <h3 className="text-xl md:text-2xl font-semibold text-slate-800 leading-relaxed mb-8">
              {currentQuestion.text}
            </h3>

            <div className="space-y-4">
              {currentQuestion.options.map((option, idx) => (
                <button
                  key={idx}
                  onClick={() => handleOptionSelect(idx)}
                  className={`w-full text-left p-4 rounded-xl border-2 transition-all flex items-center gap-4 group ${
                    answers[currentQuestion.id] === idx
                      ? 'border-blue-500 bg-blue-50 shadow-md'
                      : 'border-slate-200 hover:border-blue-300 hover:bg-slate-50'
                  }`}
                >
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center border-2 font-medium transition-colors ${
                     answers[currentQuestion.id] === idx ? 'border-blue-500 bg-blue-500 text-white' : 'border-slate-300 text-slate-500 group-hover:border-blue-400'
                  }`}>
                    {String.fromCharCode(65 + idx)}
                  </div>
                  <span className={`text-lg ${answers[currentQuestion.id] === idx ? 'text-blue-900 font-medium' : 'text-slate-700'}`}>
                    {option}
                  </span>
                </button>
              ))}
            </div>
          </div>

          <div className="p-4 border-t border-slate-100 bg-slate-50 flex justify-between items-center">
            <button
              onClick={() => setCurrentQuestionIndex(prev => Math.max(0, prev - 1))}
              disabled={currentQuestionIndex === 0}
              className="flex items-center gap-2 px-6 py-3 rounded-lg font-medium text-slate-600 disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-200 transition-colors"
            >
              <ChevronLeft size={20} /> Previous
            </button>

            {currentQuestionIndex === questions.length - 1 ? (
              <button
                onClick={() => setIsSubmitConfirmOpen(true)}
                className="flex items-center gap-2 px-8 py-3 rounded-lg font-bold text-white bg-green-600 hover:bg-green-700 shadow-md transition-colors"
              >
                Submit Test <CheckCircle size={20} />
              </button>
            ) : (
              <button
                onClick={() => setCurrentQuestionIndex(prev => Math.min(questions.length - 1, prev + 1))}
                className="flex items-center gap-2 px-8 py-3 rounded-lg font-bold text-white bg-blue-600 hover:bg-blue-700 shadow-md transition-colors"
              >
                Next <ChevronRight size={20} />
              </button>
            )}
          </div>
        </div>

        {/* Sidebar Navigation */}
        <div className="hidden md:flex flex-col w-72 bg-white rounded-2xl shadow-lg border border-slate-200 p-6">
          <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Circle size={12} className="fill-blue-500 text-blue-500" /> Question Palette
          </h3>

          <div className="grid grid-cols-5 gap-3 mb-6">
            {questions.map((q, idx) => {
              const isActive = idx === currentQuestionIndex;
              const isDone = answers[q.id] !== undefined;
              return (
                <button
                  key={idx}
                  onClick={() => setCurrentQuestionIndex(idx)}
                  className={`aspect-square rounded-lg flex items-center justify-center text-sm font-bold transition-all ${
                    isActive
                      ? 'ring-2 ring-blue-500 ring-offset-2 bg-white text-blue-600 border border-blue-200'
                      : isDone
                      ? 'bg-green-100 text-green-700 border border-green-200'
                      : 'bg-slate-100 text-slate-500 hover:bg-slate-200'
                  }`}
                >
                  {idx + 1}
                </button>
              );
            })}
          </div>

          <div className="mt-auto space-y-3 text-sm text-slate-600">
            <div className="flex justify-between items-center">
              <span>Answered</span>
              <span className="font-bold text-green-600">{answeredCount}</span>
            </div>
            <div className="flex justify-between items-center">
              <span>Unanswered</span>
              <span className="font-bold text-slate-400">{questions.length - answeredCount}</span>
            </div>
            <div className="h-2 bg-slate-100 rounded-full mt-2 overflow-hidden">
               <div className="h-full bg-green-500 transition-all duration-500" style={{ width: `${progressPercent}%` }}></div>
            </div>
          </div>
        </div>
      </div>

      {/* Mobile Sidebar (Bottom Sheet style fallback or hidden usually, simpler for this demo to rely on next/prev) */}

      {/* Confirmation Modal */}
      {isSubmitConfirmOpen && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl p-6 max-w-md w-full animate-fade-in-up">
            <div className="flex items-center gap-3 text-amber-600 mb-4">
              <AlertCircle size={32} />
              <h3 className="text-xl font-bold text-slate-900">Finish Test?</h3>
            </div>
            <p className="text-slate-600 mb-6">
              You have answered <strong className="text-slate-900">{answeredCount}</strong> out of <strong className="text-slate-900">{questions.length}</strong> questions. 
              {questions.length - answeredCount > 0 && " Are you sure you want to submit without answering all questions?"}
            </p>
            <div className="flex gap-4">
              <button
                onClick={() => setIsSubmitConfirmOpen(false)}
                className="flex-1 px-4 py-2 rounded-lg border border-slate-300 font-medium text-slate-700 hover:bg-slate-50"
              >
                Continue Reviewing
              </button>
              <button
                onClick={handleFinish}
                className="flex-1 px-4 py-2 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 shadow-md"
              >
                Submit Now
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuizScreen;

import React, { useState } from 'react';
import { Question, QuizState } from '../types';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';
import { Check, X, ArrowRight, RotateCcw, Award } from 'lucide-react';

interface ResultsScreenProps {
  questions: Question[];
  state: QuizState;
  totalTimeMinutes: number;
  onRestart: () => void;
}

const ResultsScreen: React.FC<ResultsScreenProps> = ({ questions, state, totalTimeMinutes, onRestart }) => {
  const [showSolutions, setShowSolutions] = useState(false);

  const correctCount = state.score;
  const incorrectCount = Object.keys(state.answers).length - correctCount;
  const skippedCount = questions.length - Object.keys(state.answers).length;
  const percentage = Math.round((correctCount / questions.length) * 100);

  const timeTakenSeconds = (totalTimeMinutes * 60) - state.timeRemaining;
  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}m ${s}s`;
  };

  const data = [
    { name: 'Correct', value: correctCount, color: '#10b981' },
    { name: 'Incorrect', value: incorrectCount, color: '#ef4444' },
    { name: 'Skipped', value: skippedCount, color: '#94a3b8' },
  ].filter(d => d.value > 0);

  return (
    <div className="max-w-5xl mx-auto p-6 animate-fade-in pb-20">
      <div className="text-center mb-10">
        <h1 className="text-3xl font-bold text-slate-900 mb-2">Quiz Results</h1>
        <p className="text-slate-500">Here is how you performed</p>
      </div>

      <div className="grid md:grid-cols-3 gap-6 mb-12">
        {/* Score Card */}
        <div className="bg-white p-6 rounded-2xl shadow-lg border border-slate-100 flex flex-col items-center justify-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-400 to-purple-500"></div>
          <div className="mb-4 p-4 bg-blue-50 text-blue-600 rounded-full">
            <Award size={40} />
          </div>
          <div className="text-5xl font-extrabold text-slate-900 mb-1">{percentage}%</div>
          <div className="text-slate-500 font-medium">Accuracy Score</div>
          <div className="mt-4 text-sm text-slate-400">Target: 80%+</div>
        </div>

        {/* Stats Card */}
        <div className="bg-white p-6 rounded-2xl shadow-lg border border-slate-100">
          <h3 className="text-lg font-bold text-slate-800 mb-4">Detailed Statistics</h3>
          <div className="space-y-4">
            <div className="flex justify-between items-center p-3 bg-green-50 rounded-lg">
              <span className="flex items-center gap-2 text-green-800 font-medium"><Check size={18} /> Correct</span>
              <span className="text-xl font-bold text-green-700">{correctCount}</span>
            </div>
            <div className="flex justify-between items-center p-3 bg-red-50 rounded-lg">
              <span className="flex items-center gap-2 text-red-800 font-medium"><X size={18} /> Incorrect</span>
              <span className="text-xl font-bold text-red-700">{incorrectCount}</span>
            </div>
            <div className="flex justify-between items-center p-3 bg-slate-50 rounded-lg">
              <span className="flex items-center gap-2 text-slate-600 font-medium">Skipped</span>
              <span className="text-xl font-bold text-slate-700">{skippedCount}</span>
            </div>
            <div className="mt-4 pt-4 border-t text-center text-slate-500">
              Time Taken: <span className="font-bold text-slate-800">{formatTime(timeTakenSeconds)}</span>
            </div>
          </div>
        </div>

        {/* Chart Card */}
        <div className="bg-white p-6 rounded-2xl shadow-lg border border-slate-100 flex flex-col items-center justify-center">
          <h3 className="text-lg font-bold text-slate-800 mb-2 w-full text-left">Performance Split</h3>
          <div className="h-48 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={data}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {data.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex gap-4 text-xs font-medium text-slate-500">
            {data.map((item) => (
              <div key={item.name} className="flex items-center gap-1">
                <div className="w-2 h-2 rounded-full" style={{ backgroundColor: item.color }}></div>
                {item.name}
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="flex justify-center gap-4 mb-12">
        <button
          onClick={() => setShowSolutions(!showSolutions)}
          className="px-6 py-3 bg-white border border-slate-300 hover:bg-slate-50 text-slate-700 font-bold rounded-xl shadow-sm transition-colors"
        >
          {showSolutions ? 'Hide Solutions' : 'Review Solutions'}
        </button>
        <button
          onClick={onRestart}
          className="px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl shadow-md transition-all flex items-center gap-2"
        >
          <RotateCcw size={18} /> New Test
        </button>
      </div>

      {/* Solutions Section */}
      {showSolutions && (
        <div className="space-y-6 animate-fade-in-up">
          <h2 className="text-2xl font-bold text-slate-800 mb-6">Detailed Solutions</h2>
          {questions.map((q, index) => {
            const userAnswer = state.answers[q.id];
            const isCorrect = userAnswer === q.correctAnswerIndex;
            const isSkipped = userAnswer === undefined;

            return (
              <div key={q.id} className={`bg-white rounded-xl border-l-4 p-6 shadow-sm ${
                isCorrect ? 'border-l-green-500' : isSkipped ? 'border-l-slate-400' : 'border-l-red-500'
              }`}>
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center gap-3">
                    <span className="bg-slate-100 text-slate-600 font-bold px-3 py-1 rounded text-sm">Q{index + 1}</span>
                    <span className={`text-sm font-bold px-2 py-1 rounded ${
                      isCorrect ? 'bg-green-100 text-green-700' : isSkipped ? 'bg-slate-100 text-slate-600' : 'bg-red-100 text-red-700'
                    }`}>
                      {isCorrect ? 'Correct' : isSkipped ? 'Skipped' : 'Incorrect'}
                    </span>
                  </div>
                </div>

                <h3 className="text-lg font-medium text-slate-900 mb-4">{q.text}</h3>

                <div className="grid md:grid-cols-2 gap-3 mb-4">
                  {q.options.map((opt, optIdx) => {
                    const isSelected = userAnswer === optIdx;
                    const isActuallyCorrect = optIdx === q.correctAnswerIndex;

                    let className = "p-3 rounded-lg border text-sm transition-colors ";
                    if (isActuallyCorrect) {
                      className += "bg-green-50 border-green-200 text-green-800 font-medium";
                    } else if (isSelected && !isActuallyCorrect) {
                      className += "bg-red-50 border-red-200 text-red-800";
                    } else {
                      className += "bg-white border-slate-200 text-slate-600";
                    }

                    return (
                      <div key={optIdx} className={className}>
                        <div className="flex items-center gap-2">
                          <span className="w-5 h-5 flex items-center justify-center rounded-full border text-xs bg-white/50">
                            {String.fromCharCode(65 + optIdx)}
                          </span>
                          {opt}
                          {isActuallyCorrect && <Check size={16} className="ml-auto text-green-600" />}
                          {isSelected && !isActuallyCorrect && <X size={16} className="ml-auto text-red-600" />}
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div className="bg-blue-50 p-4 rounded-lg text-sm text-blue-900">
                  <strong className="block mb-1 text-blue-700">Explanation:</strong>
                  {q.explanation}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

