import React, { useState } from 'react';
import WelcomeScreen from './components/WelcomeScreen';
import QuizScreen from './components/QuizScreen';
import ResultsScreen from './components/ResultsScreen';
import { QuizConfig, Question, QuizState } from './types';
import { generateQuestions } from './services/geminiService';

const App: React.FC = () => {
  const [appState, setAppState] = useState<'welcome' | 'quiz' | 'results'>('welcome');
  const [config, setConfig] = useState<QuizConfig | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [quizResultState, setQuizResultState] = useState<QuizState | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleStartQuiz = async (newConfig: QuizConfig) => {
    setIsLoading(true);
    setError(null);
    setConfig(newConfig);

    try {
      const generatedQuestions = await generateQuestions(
        newConfig.subject,
        newConfig.difficulty,
        newConfig.questionCount
      );
      setQuestions(generatedQuestions);
      setAppState('quiz');
    } catch (err: any) {
      console.error(err);
      setError("Failed to generate questions. Please ensure the API Key is valid or try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleFinishQuiz = (resultState: QuizState) => {
    setQuizResultState(resultState);
    setAppState('results');
  };

  const handleRestart = () => {
    setAppState('welcome');
    setConfig(null);
    setQuestions([]);
    setQuizResultState(null);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans">
      <nav className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between sticky top-0 z-10 shadow-sm">
        <div className="flex items-center gap-2 cursor-pointer" onClick={handleRestart}>
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold text-lg">
            G
          </div>
          <span className="font-bold text-xl tracking-tight text-slate-800">GovPrep AI</span>
        </div>
        <div className="text-sm text-slate-500 hidden sm:block">
          SSC • IBPS • Railways • UPSC
        </div>
      </nav>

      <main className="container mx-auto py-8 px-4">
        {error && (
          <div className="max-w-md mx-auto mb-8 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg relative" role="alert">
            <strong className="font-bold">Error! </strong>
            <span className="block sm:inline">{error}</span>
          </div>
        )}

        {appState === 'welcome' && (
          <WelcomeScreen onStart={handleStartQuiz} isLoading={isLoading} />
        )}

        {appState === 'quiz' && config && (
          <QuizScreen 
            questions={questions} 
            timeLimitMinutes={config.timeLimitMinutes}
            onFinish={handleFinishQuiz}
          />
        )}

        {appState === 'results' && quizResultState && config && (
          <ResultsScreen 
            questions={questions}
            state={quizResultState}
            totalTimeMinutes={config.timeLimitMinutes}
            onRestart={handleRestart}
          />
        )}
      </main>
    </div>
  );
};

