const STORAGE_KEY = 'shubham_aptimaster_history';

export const saveExamResult = (result: ExamResult): void => {
  try {
    const existing = getExamHistory();
    existing.push(result);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(existing));
  } catch (e) {
    console.error("Failed to save result", e);
  }
};

export const getExamHistory = (): ExamResult[] => {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) {
    return [];
  }
};

export const getSubjectAttemptCount = (subject: Subject): number => {
  const history = getExamHistory();
  return history.filter(h => h.subject === subject).length;
};

export const getTotalAttempts = (): number => {
  return getExamHistory().length;
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Subject, Difficulty, Question } from "../types";

const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error("API Key is missing.");
}

const ai = new GoogleGenAI({ apiKey: apiKey || 'dummy-key' });

export const generateQuestions = async (
  subject: Subject,
  difficulty: Difficulty,
  count: number // Arithmetic: 12, Reasoning: 25
): Promise<Question[]> => {
  const modelName = "gemini-3-flash-preview";

  let prompt = "";

  if (subject === Subject.ARITHMETIC) {
    prompt = `
      You are 'Shubham AptiMaster', a strict examiner for top-tier Indian Government Competitive Exams (SSC CGL, IBPS PO, UPSC CSAT).
      Generate exactly ${count} (12) unique, high-quality Arithmetic questions.
      Difficulty: ${difficulty}.

      MANDATORY TOPIC DISTRIBUTION (1 Question from each, fill remaining with high-weightage topics like DI or Simplification):
      1. Percentage
      2. Average
      3. Ratio & Proportion
      4. Partnership
      5. Profit and Loss
      6. Unitary Method
      7. Time and Work
      8. Time and Distance
      9. Simplification
      10. Data Interpretation (Create a text-based Caselet or simple tabular data in the question text).

      Context: Questions must be conceptually tricky but solvable within 30-45 seconds using shortcuts.
      Do not use complex LaTeX. Use plain text.
    `;
  } else {
    prompt = `
      You are 'Shubham AptiMaster', a strict examiner for Indian Government Exams.
      Generate exactly ${count} (25) unique Reasoning questions (Verbal & Non-Verbal topics compatible with text format).
      Difficulty: ${difficulty}.

      MANDATORY RULES:
      - Mix of Verbal and text-based Non-verbal (Series, Analogies, Odd one out).
      - Topics: Syllogism, Blood Relations, Directions, Coding-Decoding, Seating Arrangement (linear/circular), Series (Number/Alpha), Analogies.
      - DO NOT repeat the exact same pattern/topic logic consecutively.
      - Ensure questions challenge logical consistency.

      Context: Solvable within 30 seconds avg.
    `;
  }

  const questionSchema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.INTEGER },
        topic: { type: Type.STRING, description: "The specific topic of the question" },
        text: { type: Type.STRING, description: "The question text including any data/tables" },
        options: { 
          type: Type.ARRAY, 
          items: { type: Type.STRING },
          description: "An array of 4 possible answers"
        },
        correctAnswerIndex: { 
          type: Type.INTEGER, 
          description: "The index (0-3) of the correct answer" 
        },
        explanation: { 
          type: Type.STRING, 
          description: "Detailed step-by-step solution using short-cut methods suitable for exams." 
        }
      },
      required: ["id", "text", "options", "correctAnswerIndex", "explanation", "topic"]
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: questionSchema,
        systemInstruction: "You are a competitive exam setter. Output raw JSON only."
      }
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("No response from AI");

    const questions = JSON.parse(jsonText) as Question[];

    return questions.map((q, index) => ({
      ...q,
      id: index // Re-index to ensure safety
    }));

  } catch (error) {
    console.error("GenAI Error:", error);
    throw new Error("Exam generation failed. Please try again.");
  }
};

